public class BootLoader : MonoBehaviour
{
    [Header("Scene Configuration")]
    [SerializeField] private string mainMenuSceneName = "MainMenu";
    [SerializeField] private string gameplaySceneName = "Gameplay";

    [Header("Core Systems Prefabs")]
    [SerializeField] private GameObject audioManagerPrefab;
    [SerializeField] private GameObject inputManagerPrefab;
    [SerializeField] private GameObject poolManagerPrefab;

    private static bool _isBooted = false;

    private void Awake()
    {
        // Prevent duplicate boot on restart
        if (_isBooted)
        {
            Destroy(gameObject);
            return;
        }

        _isBooted = true;
        DontDestroyOnLoad(gameObject);

        InitializeCoreSystems();
        LoadMainMenu();
    }

    private void InitializeCoreSystems()
    {
        // Instantiate core managers (exactly once, in order)
        Instantiate(audioManagerPrefab);
        Instantiate(inputManagerPrefab);
        Instantiate(poolManagerPrefab);

        // Verify all systems initialized
        Debug.Assert(AudioManager.Instance != null, "AudioManager failed to initialize");
        Debug.Assert(InputManager.Instance != null, "InputManager failed to initialize");
        Debug.Assert(ObjectPoolManager.Instance != null, "ObjectPoolManager failed to initialize");

        Debug.Log("[BootLoader] Core systems initialized successfully.");
    }

    private void LoadMainMenu()
    {
        SceneManager.LoadScene(mainMenuSceneName, LoadSceneMode.Additive);
    }

    public static void StartGame()
    {
        // Unload menu, load gameplay additively
        SceneManager.UnloadSceneAsync("MainMenu");
        SceneManager.LoadScene("Gameplay", LoadSceneMode.Additive);
    }

    public static void ReturnToMenu()
    {
        SceneManager.UnloadSceneAsync("Gameplay");
        SceneManager.LoadScene("MainMenu", LoadSceneMode.Additive);
    }
}

