using System.Collections;

public class SceneChunkLoader : MonoBehaviour
{
    [Header("Chunk Settings")]
    [SerializeField] private float loadDistance = 50f;
    [SerializeField] private float unloadDistance = 80f;
    [SerializeField] private Transform playerTransform;

    [System.Serializable]
    public class SceneChunk
    {
        public string sceneName;
        public Vector3 worldPosition;
        [HideInInspector] public bool isLoaded;
    }

    [SerializeField] private SceneChunk[] chunks;

    private void Update()
    {
        foreach (var chunk in chunks)
        {
            float sqrDist = (chunk.worldPosition - playerTransform.position).sqrMagnitude;

            if (sqrDist < loadDistance * loadDistance && !chunk.isLoaded)
            {
                StartCoroutine(LoadChunkAsync(chunk));
            }
            else if (sqrDist > unloadDistance * unloadDistance && chunk.isLoaded)
            {
                StartCoroutine(UnloadChunkAsync(chunk));
            }
        }
    }

    private IEnumerator LoadChunkAsync(SceneChunk chunk)
    {
        AsyncOperation loadOp = SceneManager.LoadSceneAsync(chunk.sceneName, LoadSceneMode.Additive);
        loadOp.allowSceneActivation = true;

        while (!loadOp.isDone)
        {
            // Progress: 0 to 0.9 (0.9 = loaded, waiting for activation)
            float progress = Mathf.Clamp01(loadOp.progress / 0.9f);
            Debug.Log($"[SceneChunkLoader] Loading {chunk.sceneName}: {progress:P0}");
            yield return null;
        }

        chunk.isLoaded = true;
        Debug.Log($"[SceneChunkLoader] {chunk.sceneName} loaded successfully.");
    }

    private IEnumerator UnloadChunkAsync(SceneChunk chunk)
    {
        AsyncOperation unloadOp = SceneManager.UnloadSceneAsync(chunk.sceneName);
        yield return unloadOp;

        chunk.isLoaded = false;

        // Force garbage collection of unused assets (careful: causes a small hitch)
        // Use only during loading screens, not gameplay
        // Resources.UnloadUnusedAssets();

        Debug.Log($"[SceneChunkLoader] {chunk.sceneName} unloaded.");
    }
}

