public class LinqVsForLoop : MonoBehaviour
{
    [SerializeField] private List<GameObject> _enemies = new List<GameObject>();

    // Pre-allocated buffer for non-allocating results
    private readonly List<GameObject> _activeEnemiesBuffer = new List<GameObject>(50);

    // ANTI-PATTERN: LINQ in Update() — allocates every frame!
    private void Update_LINQ()
    {
        // BAD: Allocates delegate, enumerator, and new List EVERY frame
        var activeEnemies = _enemies
            .Where(e => e != null && e.activeInHierarchy)
            .OrderBy(e => Vector3.Distance(transform.position, e.transform.position))
            .ToList();

        foreach (var enemy in activeEnemies)
        {
            ProcessEnemy(enemy);
        }
    }

    // FIXED: Zero-allocation for-loop
    private void Update_ForLoop()
    {
        // Clear reusable buffer (does not deallocate memory)
        _activeEnemiesBuffer.Clear();

        // Cache count to avoid property access overhead
        int count = _enemies.Count;
        Vector3 myPosition = transform.position;

        for (int i = 0; i < count; i++)
        {
            GameObject enemy = _enemies[i];

            // Guard clauses: fast rejections first
            if (enemy == null) continue;
            if (!enemy.activeInHierarchy) continue;

            // Distance check without LINQ ordering (process as found)
            float sqrDist = (enemy.transform.position - myPosition).sqrMagnitude;
            if (sqrDist < 100f) // 10 units squared
            {
                _activeEnemiesBuffer.Add(enemy);
            }
        }

        // Process the buffer
        int activeCount = _activeEnemiesBuffer.Count;
        for (int i = 0; i < activeCount; i++)
        {
            ProcessEnemy(_activeEnemiesBuffer[i]);
        }
    }

    private void ProcessEnemy(GameObject enemy)
    {
        // Enemy processing logic...
        Debug.DrawLine(transform.position, enemy.transform.position, Color.red);
    }
}

