using UnityEngine.Events;

public class HealthComponent : MonoBehaviour, IDamageable
{
    [Header("Health Settings")] [SerializeField] private float _maxHealth = 100f;
    [Header("Unity Events")] [Tooltip("Called when health changes")] public UnityEvent<float> OnHealthChanged;
    [Tooltip("Called when health reaches zero")] public UnityEvent OnDeath;
    [Tooltip("Called when taking damage")] public UnityEvent<float> OnDamaged;
    private float _currentHealth;
    public float HealthPercent => _currentHealth / _maxHealth;
    public bool IsAlive => _currentHealth > 0;
    private void Awake() => _currentHealth = _maxHealth;
    public void TakeDamage(float amount)
    {
        if (!IsAlive) return;
        _currentHealth = Mathf.Max(0, _currentHealth - amount);
        OnDamaged?.Invoke(amount);
        OnHealthChanged?.Invoke(HealthPercent);
        if (!IsAlive) OnDeath?.Invoke();
    }
    public void Heal(float amount)
    {
        if (!IsAlive) return;
        _currentHealth = Mathf.Min(_maxHealth, _currentHealth + amount);
        OnHealthChanged?.Invoke(HealthPercent);
    }
}

