public class WaveController
{
    private readonly IEnemySpawner _spawner;
    private readonly IAudioManager _audio;
    private readonly IGameTimer _timer;
    public WaveController(IEnemySpawner spawner, IAudioManager audio, IGameTimer timer)
    {
        _spawner = spawner ?? throw new ArgumentNullException(nameof(spawner));
        _audio = audio ?? throw new ArgumentNullException(nameof(audio));
        _timer = timer ?? throw new ArgumentNullException(nameof(timer));
    }
    public void StartWave(int waveNumber)
    {
        _audio.PlayMusic("WaveMusic", 0.5f);
        _spawner.BeginSpawning(waveNumber);
        _timer.StartCountdown(60f);
    }
}

